// JAH demo program — runnable with: node demo.js
// Record JAH-APX21S-000015 — Compounded integration and acceptance suite
// Machine-checked verification: each claimed identity is recomputed and checked.
'use strict';
var checks = [{"expr": "0.82+0.11", "expect": 0.93}, {"expr": "34-7", "expect": 27}, {"expr": "12-3-1", "expect": 8}];
var fails = 0;
checks.forEach(function (ch) {
